func TestSignedReadsTakeTheHighBitAsASign(emonT *testing.T) {
	port.AssertEq(emonT, bytes.ByI8(port.HexBlob("7f 80 ff"), 0), 127, "0x7f")
	port.AssertEq(emonT, bytes.ByI8(port.HexBlob("7f 80 ff"), 1), -128, "0x80")
	port.AssertEq(emonT, bytes.ByI8(port.HexBlob("7f 80 ff"), 2), -1, "0xff")
	port.AssertEq(emonT, bytes.ByI16(port.HexBlob("7f ff 80 00 ff fe"), 0), 32767, "be 7fff")
	port.AssertEq(emonT, bytes.ByI16(port.HexBlob("7f ff 80 00 ff fe"), 2), -32768, "be 8000")
	port.AssertEq(emonT, bytes.ByI16(port.HexBlob("7f ff 80 00 ff fe"), 4), -2, "be fffe")
	port.AssertEq(emonT, bytes.ByI16le(port.HexBlob("ff 7f 00 80 fe ff"), 0), 32767, "le 7fff")
	port.AssertEq(emonT, bytes.ByI16le(port.HexBlob("ff 7f 00 80 fe ff"), 2), -32768, "le 8000")
	port.AssertEq(emonT, bytes.ByI16le(port.HexBlob("ff 7f 00 80 fe ff"), 4), -2, "le fffe")
}

func Test24BitReadsAreUnsignedInBothOrders(emonT *testing.T) {
	port.AssertEq(emonT, bytes.ByU24(port.HexBlob("01 02 03 ff ff ff"), 0), 66051, "be 010203")
	port.AssertEq(emonT, bytes.ByU24(port.HexBlob("01 02 03 ff ff ff"), 3), 16777215, "be ffffff")
	port.AssertEq(emonT, bytes.ByU24le(port.HexBlob("03 02 01 ff ff ff"), 0), 66051, "le 010203")
	port.AssertEq(emonT, bytes.ByU24le(port.HexBlob("03 02 01 ff ff ff"), 3), 16777215, "le ffffff")
}

func TestUnsigned32BitWidensWithoutGoingNegative(emonT *testing.T) {
	port.AssertEq64(emonT, bytes.ByU3264(port.HexBlob("ff ff ff ff"), 0), 4294967295, "be ffffffff")
	port.AssertEq64(emonT, bytes.ByU3264(port.HexBlob("80 00 00 00"), 0), 2147483648, "be 80000000")
	port.AssertEq64(emonT, bytes.ByU3264(port.HexBlob("00 00 01 00"), 0), 256, "be 00000100")
	port.AssertEq64(emonT, bytes.ByU32le64(port.HexBlob("ff ff ff ff"), 0), 4294967295, "le ffffffff")
	port.AssertEq64(emonT, bytes.ByU32le64(port.HexBlob("00 00 00 80"), 0), 2147483648, "le 80000000")
	port.AssertEq64(emonT, bytes.ByU32le64(port.HexBlob("00 01 00 00"), 0), 256, "le 00000100")
}

func TestBoundsQuestionsDoNotReadOutOfRange(emonT *testing.T) {
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), 0, 3), 1, "the whole blob")
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), 1, 3), 0, "one past the end")
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), 3, 0), 1, "an empty read at the end")
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), 4, 0), 0, "an empty read past the end")
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), -1, 1), 0, "a negative index")
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), 1, -1), 0, "a negative count")
	port.AssertEq(emonT, bytes.ByIn(port.HexBlob("00 01 02"), 1, 2147483647), 0, "a count that would wrap i + n")
}

func TestReadsWithADefaultAnswerItOffTheEnd(emonT *testing.T) {
	port.AssertEq(emonT, bytes.ByU8Or(port.HexBlob("0a"), 0, -1), 10, "in range")
	port.AssertEq(emonT, bytes.ByU8Or(port.HexBlob("0a"), 1, -1), -1, "one past")
	port.AssertEq(emonT, bytes.ByU16Or(port.HexBlob("01 02"), 0, -1), 258, "u16 in range")
	port.AssertEq(emonT, bytes.ByU16Or(port.HexBlob("01 02"), 1, -1), -1, "u16 straddling the end")
	port.AssertEq(emonT, bytes.ByU32Or(port.HexBlob("ff ff ff ff"), 0, 7), -1, "u32 pattern")
	port.AssertEq(emonT, bytes.ByU32Or(port.HexBlob("ff ff ff"), 0, 7), 7, "u32 short")
}

func TestSearchingForwardsAndBackwards(emonT *testing.T) {
	port.AssertEq(emonT, bytes.ByFind(port.TextBlob("abcabcab"), 0, port.TextBlob("abc")), 0, "first")
	port.AssertEq(emonT, bytes.ByFind(port.TextBlob("abcabcab"), 1, port.TextBlob("abc")), 3, "from 1")
	port.AssertEq(emonT, bytes.ByFind(port.TextBlob("abcabcab"), 4, port.TextBlob("abc")), -1, "none after 4")
	port.AssertEq(emonT, bytes.ByFind(port.TextBlob("abcabcab"), -5, port.TextBlob("cab")), 2, "negative from is 0")
	port.AssertEq(emonT, bytes.ByFind(port.TextBlob("abc"), 0, port.TextBlob("abcd")), -1, "needle longer than hay")
	port.AssertEq(emonT, bytes.ByFind(port.TextBlob("abc"), 3, port.TextBlob("")), 3, "empty needle at end")
	port.AssertEq(emonT, bytes.ByFindBack(port.TextBlob("abcabcab"), 100, port.TextBlob("abc")), 3, "last")
	port.AssertEq(emonT, bytes.ByFindBack(port.TextBlob("abcabcab"), 2, port.TextBlob("abc")), 0, "last at or before 2")
	port.AssertEq(emonT, bytes.ByFindBack(port.TextBlob("abcabcab"), 100, port.TextBlob("zz")), -1, "absent")
	port.AssertEq(emonT, bytes.ByMatchAt(port.TextBlob("abcabc"), 3, port.TextBlob("abc")), 1, "match at")
	port.AssertEq(emonT, bytes.ByMatchAt(port.TextBlob("abcabc"), 4, port.TextBlob("abc")), 0, "match runs off the end")
}
